package com.fitpulse.controller;
import com.fitpulse.model.dto.*; import com.fitpulse.model.entity.Gym; import com.fitpulse.service.GymDirectoryService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class GymDirectoryController { private final GymDirectoryService service; public GymDirectoryController(GymDirectoryService s){service=s;}
 @GetMapping("/gyms") public String list(@RequestParam(required=false)String city,@RequestParam(required=false)String q,@RequestParam(defaultValue="0")int page,Model m){m.addAttribute("gyms",service.search(city,q,page));m.addAttribute("cities",service.activeCities());m.addAttribute("city",city);m.addAttribute("q",q);return "gyms/list";}
 @GetMapping("/gyms/{slug}") public String details(@PathVariable String slug,Model m,Authentication a){Gym g=service.published(slug);m.addAttribute("gym",g);m.addAttribute("reviews",service.reviews(g));m.addAttribute("averageRating",service.rating(g));m.addAttribute("reviewForm",new ReviewForm());m.addAttribute("favorite",a!=null&&service.favorite(g));return "gyms/details";}
 @PostMapping("/gyms/{id}/favorite") public String favorite(@PathVariable Long id,@RequestParam String slug){service.toggleFavorite(id);return "redirect:/gyms/"+slug;}
 @PostMapping("/gyms/{id}/review") public String review(@PathVariable Long id,@RequestParam String slug,@Valid @ModelAttribute ReviewForm reviewForm,BindingResult errors,RedirectAttributes ra){if(errors.hasErrors())ra.addFlashAttribute("error","Оценката трябва да бъде между 1 и 5.");else{service.review(id,reviewForm);ra.addFlashAttribute("success","Оценката е запазена.");}return "redirect:/gyms/"+slug;}
 @PostMapping("/reviews/{id}/report") public String report(@PathVariable Long id,@RequestParam String slug,@RequestParam String reason,RedirectAttributes ra){service.report(id,reason);ra.addFlashAttribute("success","Сигналът е изпратен за преглед от администратор.");return "redirect:/gyms/"+slug;}
 @GetMapping("/suggest-gym") public String suggest(Model m){if(!m.containsAttribute("gymSuggestionForm"))m.addAttribute("gymSuggestionForm",new GymSuggestionForm());return "gyms/suggest";}
 @PostMapping("/suggest-gym") public String submit(@Valid @ModelAttribute GymSuggestionForm gymSuggestionForm,BindingResult errors,RedirectAttributes ra){if(errors.hasErrors())return "gyms/suggest";service.suggest(gymSuggestionForm);ra.addFlashAttribute("success","Предложението е изпратено за одобрение.");return "redirect:/suggest-gym";}
}
